16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Collection;
19	
20	/**
21	 * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}:
22	 * the upper-cased first three letters of the city and of the last name, and a
23	 * per-city 4-digit zero-padded sequence one greater than the number of owners
24	 * already in that city.
25	 */
26	public final class CustomerCode {
27	
28	    private CustomerCode() {
29	    }
30	
31	    /**
32	     * @param owner          the owner being coded (its city and last name are used)
33	     * @param existingOwners the current owners (this one excluded)
34	     * @return the formatted customer code, e.g. {@code SYD-SMI-0007}
35	     */
36	    public static String of(Owner owner, Collection<Owner> existingOwners) {
37	        long inCity = existingOwners.stream()
38	            .filter(o -> o.getCity() != null && o.getCity().equalsIgnoreCase(owner.getCity()))
39	            .count();
40	        return String.format("%s-%s-%04d", prefix3(owner.getCity()), prefix3(owner.getLastName()), inCity + 1);
41	    }
42	
43	    private static String prefix3(String value) {
44	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
45	    }
46	}
