17	
18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	
21	/**
22	 * Rolls a registration date forward onto a business day: a Saturday or Sunday
23	 * becomes the following Monday; a weekday is returned unchanged.
24	 */
25	public final class BusinessDay {
26	
27	    private BusinessDay() {
28	    }
29	
30	    /** Return {@code date} if it falls on a weekday, otherwise the next Monday. */
31	    public static LocalDate adjust(LocalDate date) {
32	        DayOfWeek day = date.getDayOfWeek();
33	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
34	            return date.plusDays(8 - day.getValue());
35	        }
36	        return date;
37	    }
38	}
