17	
18	/**
19	 * Normalises raw telephone input to E.164 form.
20	 */
21	public final class PhoneNumbers {
22	
23	    private PhoneNumbers() {
24	    }
25	
26	    /**
27	     * Convert a raw telephone string to E.164. Spaces, dashes and brackets are stripped.
28	     * A leading '+' and its country code are kept; otherwise country code '+61' is assumed
29	     * and a single leading '0' is dropped from the national digits.
30	     *
31	     * @param raw the caller-supplied telephone value
32	     * @return the E.164 representation (leading '+' followed by digits)
33	     */
34	    public static String toE164(String raw) {
35	        String digits = raw.replaceAll("\\D", "");
36	        if (raw.indexOf('+') >= 0) {
37	            return "+" + digits;
38	        }
39	        if (digits.startsWith("0")) {
40	            digits = digits.substring(1);
41	        }
42	        return "+61" + digits;
43	    }
44	}
