32	     * @return the membership level from {@code 1} to {@code 3}
33	     */
34	    public static int of(Integer namesakeCount, String email) {
35	        int level = 1;
36	        if (email != null && !email.isBlank()) {
37	            level++;
38	        }
39	        if (Integer.valueOf(0).equals(namesakeCount)) {
40	            level++;
41	        }
42	        return Math.min(level, 3);
43	    }
44	}
